#[derive(Clone,Copy,Default)]pub struct Camera{pub x:i32,pub y:i32} #[derive(Clone,Copy)]pub struct Sprite{pub asset:u64,pub x:i16,pub y:i16,pub layer:i16} #[derive(Default)]pub struct Renderer{pub camera:Camera,q:Vec<Sprite>} impl Renderer{pub fn push(&mut self,s:Sprite){self.q.push(s)}pub fn sorted(&mut self)->&[Sprite]{self.q.sort_by_key(|s|s.layer);&self.q}pub fn clear(&mut self){self.q.clear()}}
